        length, dist, status = queue.popleft()
        if (status == 0 and length == dist) or (status == 1 and length == dist + h) or (status == 2 and length == dist + h):
            return length
        if status == 0:
            if f < a:
                queue.append((length, dist, 1))
                queue.append((length + abs(f - a), dist + h, 2))
